package com.masterclass.inventory.repository; import com.masterclass.inventory.entity.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.OffsetDateTime;import java.util.*; public interface ProductRepository extends JpaRepository<Product,Long>{ Optional<Product> findBySku(String sku); boolean existsBySku(String sku); List<Product> findByCurrentStockLessThanEqualAndStatus(int reorderLevel, ProductStatus status); @Query("select p from Product p where lower(p.name) like lower(concat('%', :term, '%')) or lower(p.sku) like lower(concat('%', :term, '%'))") List<Product> search(@Param("term") String term); }
